import { setupWorker } from 'msw/browser';
import { handlers } from './handlers';

/**
 * Starts the MSW service worker (public/mockServiceWorker.js, generated by `npx msw init public/`) when
 * features.mocks is on. Only the phase 2 paths are intercepted; every other request passes through to the edge.
 */
export async function startMocks(): Promise<void> {
  const worker = setupWorker(...handlers);
  await worker.start({ onUnhandledRequest: 'bypass', serviceWorker: { url: '/mockServiceWorker.js' } });
  console.info('[announce] MSW mocks active for the trade and chat contracts');
}
